   404
   405          // force rotation out of missing k-axes sub-sequence
   406          if (_h3LeadingNonZeroDigit(current) == K_AXES_DIGIT) {
   407              if (oldBaseCell != newBaseCell) {
   408                  // in this case, we traversed into the deleted
   409                  // k subsequence of a pentagon base cell.
   410                  // We need to rotate out of that case depending
   411                  // on how we got here.
   412                  // check for a cw/ccw offset face; default is ccw
   413
   414                  if (_baseCellIsCwOffset(
   415                          newBaseCell, baseCellData[oldBaseCell].homeFijk.face)) {
   416                      current = _h3Rotate60cw(current);
   417                  } else {
   418                      // See cwOffsetPent in testGridDisk.c for why this is
   419                      // unreachable.
   420                      current = _h3Rotate60ccw(current);  // LCOV_EXCL_LINE
   421                  }
   422                  alreadyAdjustedKSubsequence = 1;
